const app=document.getElementById('app');let me=null,currentPage='dashboard',jobsCache=[],assessmentCache=[],appliedJobIds=new Set();const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok||d.error)throw Error(d.error||`Request failed (${r.status})`);return d}
function toast(msg){const t=$('#toast');t.textContent=msg;t.style.opacity=1;t.style.transform='translateY(0)';clearTimeout(window.tt);window.tt=setTimeout(()=>{t.style.opacity=0;t.style.transform='translateY(8px)'},2600)}
function initials(){return (me?.name||'Guest').trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'G'}
function theme(){const x=localStorage.getItem('studentgig-theme')||'light';document.body.classList.toggle('dark',x==='dark');$('#themeIcon').textContent=x==='dark'?'☀':'☾';$('#themeLabel').textContent=x==='dark'?'Light mode':'Dark mode'}
$('#themeToggle').onclick=()=>{const d=!document.body.classList.contains('dark');document.body.classList.toggle('dark',d);localStorage.setItem('studentgig-theme',d?'dark':'light');theme()};$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#logout').onclick=logout;
function nav(){const isAdmin=me?.role==='ADMIN';const isRecruiter=me?.role==='RECRUITER';const career=isAdmin?[]:isRecruiter?[['recruiter','▣','Recruiter Dashboard']]:[['dashboard','⌂','Dashboard'],['jobs','▣','Job Marketplace'],['applications','✓','Applications'],['companies','◈','Companies']];const growth=isAdmin||isRecruiter?[]:[['profile','◎','My Profile'],['career','↗','Career Studio'],['resume','▤','AI Resume Builder'],['freelance','◆','Freelancing'],['code','</>','Online Compiler']];$('#navCareer').innerHTML=career.map(x=>nb(...x)).join('');$('#navGrowth').innerHTML=growth.map(x=>nb(...x)).join('');$('#adminNav').innerHTML=isAdmin?`<div class="side-caption">ADMIN ONLY</div><nav>${nb('admin','⚙','Admin Control')}</nav>`:isRecruiter?`<div class="side-caption">COMPANY</div><nav>${nb('recruiter','🏢','Recruiter Workspace')}</nav>`:'';document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>route(b.dataset.page))}
function nb(p,i,t){return `<button class="nav-btn ${currentPage===p?'active':''}" data-page="${p}"><span class="nav-icon">${i}</span>${t}</button>`}
function header(t,s){$('#pageTitle').textContent=t;$('#pageSub').textContent=s;$('#topName').textContent=me?.name||'Guest';$('#topAvatar').textContent=initials();nav()}
async function init(){theme();try{const x=await api('/api/auth/me');me=x?.loggedIn===false?null:x}catch(e){me=null}if(me){header('Dashboard','Your career command center');route('dashboard')}else showAuth()}
function showAuth(mode='login',err=''){document.querySelector('.sidebar').style.display='none';document.querySelector('.main').style.display='none';const a=$('#authScreen');a.innerHTML=`<div class="auth"><div class="auth-copy"><div class="brand"><span class="logo">S</span><span>Student<span>Gig</span></span></div><h1>Build your career. Find your next opportunity.</h1><p>A modern career platform for students to discover jobs, build a professional profile, practice assessments and create an ATS-ready resume.</p><div class="auth-features"><span>Career-first jobs</span><span>AI Resume Builder</span><span>Assessments</span><span>Freelance marketplace</span></div></div><div class="auth-panel"><div class="auth-box"><div class="brand"><span class="logo">S</span><span>Student<span>Gig</span></span></div><h2>${mode==='login'?'Welcome back':'Create your account'}</h2><p>${mode==='login'?'Sign in to continue your career journey.':'Create your profile and start discovering opportunities.'}</p><div class="auth-tabs"><button class="${mode==='login'?'active':''}" onclick="showAuth('login')">Login</button><button class="${mode==='register'?'active':''}" onclick="showAuth('register')">Register</button></div>${err?`<div class="auth-error">${esc(err)}</div>`:''}<form class="form" onsubmit="authSubmit(event,'${mode}')">${mode==='register'?`<div><span class="label">FULL NAME</span><input id="aname" required placeholder="Your full name"></div>`:''}<div><span class="label">EMAIL</span><input id="aemail" type="email" required placeholder="you@example.com"></div><div><span class="label">PASSWORD</span><input id="apass" type="password" minlength="6" required placeholder="At least 6 characters"></div>${mode==='register'?`<div><span class="label">ACCOUNT TYPE</span><select id="arole"><option value="STUDENT">Student</option><option value="RECRUITER">Recruiter / Company</option></select></div>`:''}<button class="btn" type="submit">${mode==='login'?'Sign in':'Create account'}</button></form>${mode==='login'?`<div class="notice" style="margin-top:14px"><b>Admin access</b><br>Use the configured admin email and password. Admin accounts are not created through public registration.</div>`:''}</div></div></div>`;}
async function authSubmit(e,mode){e.preventDefault();try{if(mode==='login'){me=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#aemail').value,password:$('#apass').value})});}else{const u={name:$('#aname').value,email:$('#aemail').value,password:$('#apass').value,role:$('#arole').value};await api('/api/auth/register',{method:'POST',body:JSON.stringify(u)});me=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:u.email,password:u.password})});}$('#authScreen').innerHTML='';document.querySelector('.sidebar').style.display='flex';document.querySelector('.main').style.display='block';header('Dashboard','Your career command center');route('dashboard');toast(`Welcome, ${me.name}`)}catch(e){showAuth(mode,e.message)}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch(e){}me=null;showAuth('login');toast('You have been logged out')}
function route(p){if(!me)return showAuth();if(me.role==='ADMIN'&&p!=='admin')p='admin';if(me.role==='RECRUITER'&&['dashboard','jobs','applications','companies','profile','career','resume','freelance','code'].includes(p))p='recruiter';if(me.role!=='ADMIN'&&me.role!=='RECRUITER'&&p==='admin')p='dashboard';currentPage=p;$('#sidebar').classList.remove('open');const map={recruiter:['Recruiter Dashboard','Manage your company, jobs and candidates'],code:['Code Lab','Practice Java and Python with custom test cases'],dashboard:['Dashboard','Your career command center'],jobs:['Job Marketplace','Discover work that fits your goals'],applications:['Applications','Track every opportunity in one place'],companies:['Companies','Explore verified employers'],profile:['My Profile','Build a profile recruiters remember'],career:['Career Studio','Measure skills, practice and plan your next step'],resume:['AI Resume Builder','Create a polished, ATS-friendly resume'],freelance:['Freelancing','A separate space for project-based work'],admin:['Admin Control','Manage the platform, assessments and proctoring']};const x=map[p]||map.dashboard;header(...x);({recruiter:recruiterDashboard,code:codeLab,dashboard:dashboard,jobs:jobs,applications:applications,companies:companies,profile:profile,career:career,resume:resume,freelance:freelance,admin:admin}[p]||dashboard)()}
async function dashboard(){let jobs=[];try{jobs=await api('/api/jobs')}catch(e){}jobsCache=jobs;const score=profileScore();app.innerHTML=`<div class="card hero"><div><h2>Good to see you, ${esc(me.name?.split(' ')[0]||'there')} 👋</h2><p>Your next opportunity is closer than you think. Complete your profile, explore roles and keep your career progress moving.</p><div style="margin-top:17px;display:flex;gap:8px"><button class="btn" onclick="route('jobs')">Explore jobs</button><button class="btn secondary" onclick="route('profile')">Complete profile</button></div></div><div class="hero-side"><small>PROFILE READINESS</small><strong>${score}%</strong><small>${score>=80?'Recruiter-ready':'Complete more sections'}</small></div></div><div class="grid section"><div class="card stat"><small>Open opportunities</small><strong>${jobs.length}</strong><span class="delta">Fresh roles to explore</span></div><div class="card stat"><small>Applications</small><strong id="dashApps">—</strong><span class="delta">Track your progress</span></div><div class="card stat"><small>Profile completion</small><strong>${score}%</strong><span class="delta">Higher visibility</span></div><div class="card stat"><small>Career tools</small><strong>06</strong><span class="delta">Skills, tests & resume</span></div></div><div class="grid2 section"><div class="card"><div class="section-head"><h2>Recommended opportunities</h2><button class="link" onclick="route('jobs')">View all</button></div><div class="jobs">${jobs.slice(0,4).map(jobCard).join('')||empty('No jobs yet','Create jobs from an admin or recruiter account.')}</div></div><div class="card"><div class="section-head"><h2>Career checklist</h2></div>${check('Profile','Add your skills, links and education',score>=50)}${check('Resume','Build your professional resume',!!me.resumePath)}${check('Assessment','Take a skill assessment',true)}${check('Interview','Practice interview questions',false)}</div></div>`;try{$('#dashApps').textContent=(await api('/api/applications/me')).length}catch(e){}}
function check(t,s,done){return `<div style="display:flex;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)"><span class="pill">${done?'✓':'○'}</span><div><b style="font-size:11px">${t}</b><div class="meta">${s}</div></div></div>`}
function jobCard(j){const applied=appliedJobIds.has(Number(j.id));return `<div class="card job"><div class="job-main"><div class="company-logo">${esc((j.company||'C').charAt(0))}</div><div><h3>${esc(j.title||'Untitled role')}</h3><div class="meta">${esc(j.company||'Company')} · ${esc(j.location||'Location')} · ${esc(j.workMode||'Flexible')}</div><div class="tags">${String(j.skills||'').split(',').filter(Boolean).slice(0,4).map(x=>`<span class="tag">${esc(x.trim())}</span>`).join('')}<span class="tag">${esc(j.type||'Job')}</span></div></div></div>${applied?'<button class="btn secondary" disabled>✓ Applied</button>':`<button class="btn" onclick="applyJob(${j.id},this)">Apply</button>`}</div>`}
async function jobs(){let list=[];try{list=jobsCache=await api('/api/jobs');const apps=await api('/api/applications/me');appliedJobIds=new Set(apps.map(a=>Number(a.jobId)))}catch(e){toast(e.message)}app.innerHTML=`<div class="card"><div class="toolbar"><input id="jq" class="input" placeholder="Search title, company or skill"><select id="jt"><option value="">All work types</option><option>Full-time</option><option>Part-time</option><option>Internship</option><option>Freelance</option><option>Contract</option><option>Temporary</option><option>Apprenticeship</option><option>Volunteer</option><option>Trainee</option><option>Graduate Program</option></select><select id="jm"><option value="">All work modes</option><option>Remote</option><option>Hybrid</option><option>On-site</option></select><button class="btn" onclick="filterJobs()">Search</button></div><div class="jobs" id="jobList">${list.map(jobCard).join('')||empty('No opportunities found','Try another search or check back later.')}</div></div>`}
async function filterJobs(){const q=$('#jq').value,type=$('#jt').value,location=$('#jm').value;let list=await api(`/api/jobs?q=${encodeURIComponent(q)}&type=${encodeURIComponent(type)}&location=${encodeURIComponent(location)}`);$('#jobList').innerHTML=list.map(jobCard).join('')||empty('No matching jobs','Try another combination of filters.')}
function applyJob(id,button){
  const jobId=Number(id);
  if(!Number.isInteger(jobId)||jobId<=0){toast('Invalid job selected');return;}
  const job=jobsCache.find(j=>Number(j.id)===jobId);
  openModal('Apply for this job',`<form class="form" onsubmit="submitJobApplication(event,${jobId})">
    <div class="notice"><b>${esc(job?.title||'Job Application')}</b><br>${esc(job?.company||'Company')} · ${esc(job?.location||'Location')} · ${esc(job?.workMode||'Flexible')}</div>
    <div><span class="label">RESUME (PDF ONLY)</span><input id="applyResume" class="field" type="file" accept="application/pdf,.pdf" required><div class="meta" style="margin-top:6px">Upload your current resume. Maximum size: 5 MB.</div></div>
    <div><span class="label">COVER LETTER (OPTIONAL)</span><textarea id="applyCover" class="field" placeholder="Write a short message to the recruiter..."></textarea></div>
    <div style="display:flex;justify-content:flex-end;gap:8px"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button id="submitApplyBtn" class="btn" type="submit">Submit Application</button></div>
  </form>`);
}

async function submitJobApplication(e,id){
  e.preventDefault();
  const file=$('#applyResume')?.files?.[0];
  const btn=$('#submitApplyBtn');
  if(!file){toast('Please upload your resume PDF');return;}
  if(!file.name.toLowerCase().endsWith('.pdf') || (file.type && file.type!=='application/pdf')){toast('Only PDF resumes are allowed');return;}
  if(file.size>5*1024*1024){toast('Resume must be 5 MB or smaller');return;}
  const form=new FormData();
  form.append('jobId',String(Number(id)));
  form.append('resume',file,file.name);
  form.append('coverLetter',$('#applyCover')?.value||'Interested in this opportunity.');
  if(btn){btn.disabled=true;btn.textContent='Submitting...';}
  try{
    const r=await fetch('/api/applications/with-resume',{method:'POST',credentials:'same-origin',body:form});
    const d=await r.json().catch(()=>({}));
    if(!r.ok||d.error)throw Error(d.error||`Request failed (${r.status})`);
    appliedJobIds.add(Number(id));
    closeModal();
    openModal('Application Submitted',`<div class="card" style="text-align:center"><div style="font-size:42px">✓</div><h3 style="margin:10px 0">You have applied successfully</h3><p class="meta">Your PDF resume was uploaded and attached to this application.</p><button class="btn" onclick="closeModal();route('applications')">View My Applications</button></div>`);
    await jobs();
  }catch(err){
    toast(err.message||'Could not submit application');
    if(btn){btn.disabled=false;btn.textContent='Submit Application';}
  }
}

async function applications(){let x=[];try{x=await api('/api/applications/me')}catch(e){toast(e.message||'Could not load applications')}app.innerHTML=`<div class="card"><div class="section-head"><h2>Application tracker</h2><span class="pill">${x.length} total</span></div>${x.length?`<table class="table"><thead><tr><th>Job</th><th>Company</th><th>Status</th><th>Applied</th></tr></thead><tbody>${x.map(a=>{const j=jobsCache.find(j=>Number(j.id)===Number(a.jobId));return `<tr><td>${esc(j?.title||('#'+a.jobId))}</td><td>${esc(j?.company||'')}</td><td><span class="pill">${esc(a.status)}</span></td><td>${esc(a.appliedAt||'')}</td></tr>`}).join('')}</tbody></table>`:empty('No applications yet','Apply to a job and its progress will appear here.')}</div>`}
async function companies(){
 let x=[];try{x=await api('/api/companies')}catch(e){toast(e.message)}
 app.innerHTML=`<div class="grid2"><div class="card"><div class="section-head"><h2>Employer directory</h2><span class="pill">${x.length} companies</span></div><div class="jobs">${x.map(c=>`<div class="job"><div class="job-main"><div class="company-logo">${esc((c.name||'C')[0])}</div><div><h3>${esc(c.name)}</h3><div class="meta">${esc(c.industry||'Industry')} · ${esc(c.location||'Location')}</div><div class="tags"><span class="tag">${c.verified?'✓ Verified':'Company'}</span></div></div></div><button class="btn secondary" onclick="viewCompanyJobs(${c.id},'${esc(c.name)}')">View jobs</button></div>`).join('')||empty('No companies yet','Recruiters can add companies from their workspace.')}</div></div><div class="card"><h2>Company jobs</h2><p class="meta" style="line-height:1.7;margin-top:10px">Choose a company to see only jobs published under that company. Recruiter-added companies and jobs appear here automatically.</p></div></div>`
}
async function viewCompanyJobs(companyId,name){try{const list=await api('/api/jobs/company/'+companyId);openModal(esc(name)+' — Jobs',list.length?`<div class="jobs">${list.map(jobCard).join('')}</div>`:empty('No jobs for this company','This company has not published jobs yet.'))}catch(e){toast(e.message)}}
function profileScore(){if(!me)return 0;const fields=['name','bio','phone','location','degree','graduationYear','skills','experience','languages','github','linkedin','portfolio','leetcode','resumePath'];return Math.round(fields.filter(k=>me[k]&&String(me[k]).trim()).length/fields.length*100)}
function profile(){const fields=['name','phone','location','degree','graduationYear','skills','experience','languages','availability','github','linkedin','portfolio','leetcode','hackerrank','codechef','gfg','kaggle','bio'];app.innerHTML=`<div class="profile-grid"><div class="card profile-head"><div class="big-avatar">${esc(initials())}</div><h2 style="margin:0 0 4px;font-size:18px">${esc(me.name)}</h2><div class="meta">${esc(me.degree||'Student')} ${me.graduationYear?'· '+me.graduationYear:''}</div><div style="text-align:left;margin-top:22px"><div class="section-head"><span class="meta">Profile completion</span><b style="font-size:11px">${profileScore()}%</b></div><div class="progress"><span style="width:${profileScore()}%"></span></div></div><div class="notice" style="margin-top:18px;text-align:left">Tip: use the AI Resume Builder after updating your profile to turn your details into professional resume content.</div></div><div class="card"><div class="section-head"><h2>Professional profile</h2><button class="btn" onclick="saveProfile()">Save changes</button></div><div class="form-grid">${fields.map(k=>`<div class="${k==='bio'?'full':''}"><span class="label">${k.replace(/([A-Z])/g,' $1').toUpperCase()}</span>${k==='bio'||k==='experience'?`<textarea id="p_${k}" placeholder="${k==='bio'?'A concise professional introduction':'Describe responsibilities and measurable results'}">${esc(me[k]||'')}</textarea>`:`<input class="field" id="p_${k}" value="${esc(me[k]||'')}" placeholder="${k.replace(/([A-Z])/g,' $1')}">`}</div>`).join('')}</div></div></div>`}
async function saveProfile(){const keys=['name','phone','location','degree','graduationYear','skills','experience','languages','availability','github','linkedin','portfolio','leetcode','hackerrank','codechef','gfg','kaggle','bio'];const p={};keys.forEach(k=>p[k]=$(`#p_${k}`).value);if(p.graduationYear)p.graduationYear=Number(p.graduationYear);try{me=await api('/api/profile',{method:'PUT',body:JSON.stringify(p)});toast('Profile saved');profile()}catch(e){toast(e.message)}}
async function career(){let tests=[],mine=[];try{tests=await api('/api/assessments');mine=await api('/api/assessments/my-attempts')}catch(e){toast(e.message)}assessmentCache=tests;app.innerHTML=`<div class="card admin-hero hero"><div><h2>Career Studio</h2><p>Build job-ready skills with assessments, interview practice, skill-gap insights and your professional resume.</p></div><div class="hero-side"><small>READINESS</small><strong>${profileScore()}%</strong><small>Profile strength</small></div></div><div class="career-grid section"><div class="card tool"><div class="tool-icon">◌</div><h3>Skill Gap Analysis</h3><p>See which skills to strengthen for the roles you want.</p><button class="btn" onclick="skillGap()">Analyze skills</button></div><div class="card tool"><div class="tool-icon">★</div><h3>Job Match Finder</h3><p>Jump directly to roles filtered around your profile.</p><button class="btn" onclick="route('jobs')">Find jobs</button></div><div class="card tool"><div class="tool-icon">?</div><h3>Interview Practice</h3><p>Practice technical and behavioral questions with a guided session.</p><button class="btn" onclick="interview()">Start practice</button></div><div class="card tool"><div class="tool-icon">✓</div><h3>Assessments</h3><p>Timed MCQ and coding assessments with configurable proctoring.</p><button class="btn" onclick="assessmentList()">Browse tests</button></div></div><div class="card section"><div class="section-head"><h2>My Test Results</h2><span class="pill">${mine.length} attempts</span></div>${mine.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Assessment ID</th><th>Marks</th><th>Total</th><th>Score</th><th>Violations</th><th>Submitted</th></tr></thead><tbody>${mine.map(a=>`<tr><td>#${a.assessmentId}</td><td>${a.score||0}</td><td>${a.total||0}</td><td>${a.total?Math.round((a.score||0)*100/a.total):0}%</td><td>${a.violations||0}${a.autoSubmitted?' <span class="pill">Auto</span>':''}</td><td>${esc(a.submittedAt||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('No test attempts yet','Take a published assessment and your marks will appear here.')}</div><div class="card section"><div class="section-head"><h2>Published assessments</h2><span class="pill">${tests.length} available</span></div>${tests.slice(0,8).map(a=>`<div class="job"><div><h3>${esc(a.title)}</h3><div class="meta">${esc(a.category||'General')} · ${a.durationMinutes||30} min · ${a.cheatLimit??3} violations · ${a.detectTabSwitch?'Tab detection enabled':''}</div></div><button class="btn" onclick="startAssessment(${a.id})">Start Test</button></div>`).join('')||empty('No assessments published','Your administrator can create the first test.')}</div>`}
function skillGap(){const s=String(me.skills||'').split(',').map(x=>x.trim()).filter(Boolean);openModal('Skill Gap Analysis',`<div class="notice">Your current skills</div><div class="tags" style="margin:12px 0">${(s.length?s:['No skills listed']).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><h3>Next actions</h3><div class="card" style="box-shadow:none;margin-top:10px"><p class="meta">1. Add 2–3 target skills to your profile.</p><p class="meta">2. Take one assessment related to your target role.</p><p class="meta">3. Add a project with measurable outcomes.</p></div>`)}
function interview(){const qs=['Tell me about yourself and your strongest technical skill.','Describe a project where you solved a difficult problem.','How would you debug a slow Java API?','Why are you interested in this role?'];openModal('Interview Practice',`<div class="notice">Use the STAR structure: Situation → Task → Action → Result.</div>${qs.map((q,i)=>`<div class="assessment-q"><strong>${i+1}. ${q}</strong><textarea style="margin-top:8px" placeholder="Write your answer..."></textarea></div>`).join('')}<button class="btn" onclick="closeModal();toast('Practice session saved for this session')">Finish practice</button>`) }
async function assessmentList(){let x=assessmentCache;try{x=await api('/api/assessments')}catch(e){}openModal('Assessments',x.length?x.map(a=>`<div class="card" style="margin-bottom:9px;box-shadow:none"><div class="section-head"><b>${esc(a.title)}</b><span class="pill">${a.category||'General'}</span></div><div class="meta" style="margin:6px 0">${a.durationMinutes||30} min · ${a.cheatLimit??3} violations · ${a.requireCamera?'Camera required':''}</div><button class="btn" onclick="closeModal();startAssessment(${a.id})">Start assessment</button></div>`).join(''):empty('No assessments published','Ask an administrator to publish one.'))}
async function startAssessment(id){
  let a=await api('/api/assessments/'+id),qs=[];
  try{qs=JSON.parse(a.questionsJson||'[]')}catch(e){toast('Assessment questions are invalid');return}

  let violations=0,stream=null,finished=false,visibilityHandler=null,blurHandler=null,fullscreenHandler=null,lastViolationAt=0,lastViolationType='';
  const limit=Math.max(1,a.cheatLimit||3);
  const mobile=/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
  if(a.blockMobile&&mobile){toast('This assessment is configured for desktop devices only.');return}

  const overlay=document.createElement('div');
  overlay.className='proctor active';
  // Disable clipboard-based shortcuts only while an exam is active.
  // Typing normally remains enabled, including inside the coding editor.

  overlay.id='proctor';
  overlay.innerHTML=`<div class="exam-shell"><div class="exam-head"><div><b>${esc(a.title)}</b><div class="meta" style="color:#b9c5dd">${esc(a.category||'Assessment')}</div></div><span id="timer">${a.durationMinutes||30}:00</span><span class="violation" id="vtext">Violations: 0 / ${limit}</span></div><div class="exam-body"><div class="proctor-status"><span class="status-dot">${a.requireCamera?'● Camera':'○ Camera optional'}</span><span class="status-dot">${a.detectTabSwitch?'● Tab detection':'○ Tab detection off'}</span><span class="status-dot">${a.requireFullscreen?'● Fullscreen required':'○ Fullscreen optional'}</span></div><div class="notice" style="margin:12px 0">Use Next Question to continue. Your selected answer/code is saved while you move through the test. Use Submit Assessment on the final question or Submit Now at any time. Switching tabs or leaving the exam window may create a warning.</div><div id="proctorWarning" style="display:none;margin:12px 0;padding:12px 14px;border:1px solid rgba(255,180,80,.35);background:rgba(255,180,80,.10);border-radius:12px;color:#ffd89a;font-weight:700"></div><div id="examProgress" class="meta" style="margin-bottom:10px"></div><div id="examQuestion"></div><div id="examNav" style="display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:14px;flex-wrap:wrap"></div></div></div><video id="cam" autoplay muted playsinline></video>`;
  document.body.appendChild(overlay);

  const blockClipboard=(e)=>{
    const type=e.type;
    if(['copy','cut','paste','drop'].includes(type)){
      e.preventDefault();
      e.stopPropagation();
      showWarning('⚠ Copy/paste is disabled during the assessment. Type your answer manually.');
      return;
    }
    if(type==='keydown'){
      const k=String(e.key||'').toLowerCase();
      const mod=e.ctrlKey||e.metaKey;
      const blockedCombo=mod&&['c','v','x'].includes(k);
      const blockedInsert=e.key==='Insert'&&e.shiftKey;
      if(blockedCombo||blockedInsert){
        e.preventDefault(); e.stopPropagation();
        showWarning('⚠ Copy/paste shortcuts are disabled during the assessment.');
      }
    }
  };
  ['copy','cut','paste','drop','keydown'].forEach(ev=>overlay.addEventListener(ev,blockClipboard,true));
  const clearClipboardHandlers=()=>['copy','cut','paste','drop','keydown'].forEach(ev=>overlay.removeEventListener(ev,blockClipboard,true));

  const answers={};
  let current=0;

  const showWarning=(message)=>{
    const box=$('#proctorWarning');
    if(!box)return;
    box.textContent=message;
    box.style.display='block';
    clearTimeout(box._hideTimer);
    box._hideTimer=setTimeout(()=>{if(box)box.style.display='none'},4500);
  };

  const isDuplicateBrowserEvent=(reason,now)=>{
    const lower=String(reason||'').toLowerCase();
    const type=(lower.includes('tab switch')||lower.includes('window focus'))?'browser-leave':(lower.includes('fullscreen')?'fullscreen':String(reason||''));
    if(type==='browser-leave' && lastViolationType==='browser-leave' && now-lastViolationAt<1200)return true;
    if(type==='fullscreen' && lastViolationType==='fullscreen' && now-lastViolationAt<1200)return true;
    lastViolationType=type; lastViolationAt=now; return false;
  };

  const violation=reason=>{
    if(finished)return;
    const now=Date.now();
    if(isDuplicateBrowserEvent(reason,now))return;
    violations++;
    const el=$('#vtext');
    if(el)el.textContent=`Violations: ${violations} / ${limit}`;
    const message=`⚠ Proctoring warning ${violations}/${limit}: ${reason}`;
    toast(message); showWarning(message);
    if(violations>=limit){
      showWarning(`Violation limit reached (${violations}/${limit}). Your assessment is being submitted automatically.`);
      toast('Violation limit reached. Assessment submitted automatically.');
      window.finishExam(true);
    }
  };

  const saveCurrent=()=>{
    const q=qs[current];
    if(!q)return;
    const type=String(q.type||'MCQ').toUpperCase();
    if(type==='CODING'){
      const code=$('#examCode')?.value;
      if(code!==undefined)answers[String(current)]=code;
    }else{
      const r=document.querySelector(`input[name="examOption"]:checked`);
      if(r)answers[String(current)]=r.value;
    }
  };

  const renderQuestion=()=>{
    if(finished)return;
    const q=qs[current]||{};
    const type=String(q.type||'MCQ').toUpperCase();
    const saved=answers[String(current)]||'';
    $('#examProgress').textContent=`Question ${current+1} of ${qs.length}`;
    let html='';
    if(type==='CODING'){
      const starter=q.starterCode||'public class Main {\n  public static void main(String[] args) {\n    // your code\n  }\n}';
      html=`<div class="assessment-q"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start"><strong>${current+1}. ${esc(q.question||'Coding question')}</strong><span class="pill">CODING · ${esc(q.language||'java')}</span></div><p class="meta" style="margin:10px 0">Sample input:<br><span style="white-space:pre-wrap">${esc(q.sampleInput||'No sample input')}</span><br><br>Expected output:<br><span style="white-space:pre-wrap">${esc(q.sampleOutput||'Not specified')}</span></p><textarea class="exam-code" id="examCode" spellcheck="false" placeholder="Write your code here...">${esc(saved||starter)}</textarea><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><button class="btn secondary" type="button" onclick="window.runCurrentExamCode()">▶ Run Code</button><button class="btn secondary" type="button" onclick="window.clearCurrentExamOutput()">Clear Output</button></div><pre class="output" id="examCodeOutput" style="min-height:90px;margin-top:8px">Run your code against the sample input.</pre></div>`;
    }else{
      html=`<div class="assessment-q"><strong>${current+1}. ${esc(q.question||'Question')}</strong><div style="margin-top:10px">${(q.options||[]).map((o,i)=>`<label><input type="radio" name="examOption" value="${esc(o)}" ${saved&&String(saved).trim().toLowerCase()===String(o).trim().toLowerCase()?'checked':''}> ${esc(o)}</label>`).join('')}</div></div>`;
    }
    $('#examQuestion').innerHTML=html;
    $('#examNav').innerHTML=`<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn secondary" type="button" ${current===0?'disabled':''} onclick="window.prevExamQuestion()">← Previous</button><button class="btn secondary" type="button" onclick="window.submitExamNow()">Submit Now</button></div><button class="btn" type="button" onclick="window.nextExamQuestion()">${current===qs.length-1?'Submit Assessment':'Next Question →'}</button>`;
  };

  window.runCurrentExamCode=async()=>{
    saveCurrent();
    const q=qs[current]||{};
    const code=$('#examCode')?.value||'';
    const out=$('#examCodeOutput');
    if(!code.trim()){out.textContent='Write code first.';return}
    out.textContent='Compiling and running...';
    try{
      const r=await api('/api/compiler/run',{method:'POST',body:JSON.stringify({language:q.language||'java',code,input:q.sampleInput||''})});
      const text=r.success ? (r.output||'Program finished with no output.') : (r.error||r.output||'Compiler error.');
      out.textContent=text + (r.stage?`\n\nStage: ${r.stage}`:'');
    }catch(e){out.textContent=e.message}
  };
  window.clearCurrentExamOutput=()=>{const o=$('#examCodeOutput');if(o)o.textContent='Run your code against the sample input.'};
  window.prevExamQuestion=()=>{saveCurrent();if(current>0){current--;renderQuestion()}};
  window.nextExamQuestion=()=>{saveCurrent();if(current<qs.length-1){current++;renderQuestion()}else{window.finishExam(false)}};
  window.submitExamNow=()=>{
    const box=$('#proctorWarning');
    if(box){box.style.display='block';box.textContent='Click Submit Assessment again to confirm submission.'}
    const nav=$('#examNav');
    if(nav){
      const btn=nav.querySelector('button:last-child');
      if(btn){btn.textContent='Confirm Submit';btn.onclick=()=>{saveCurrent();window.finishExam(false)}}
    }
  };

  if(a.requireCamera&&navigator.mediaDevices?.getUserMedia){
    try{
      stream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});
      $('#cam').srcObject=stream;
      const track=stream.getVideoTracks()[0];
      if(track)track.addEventListener('ended',()=>violation('camera disconnected'));
    }catch(e){violation('camera permission denied')}
  }else if(a.requireCamera){violation('camera unavailable')}

  if(a.detectTabSwitch)visibilityHandler=()=>{if(document.hidden)violation('tab switch detected')};
  if(visibilityHandler)document.addEventListener('visibilitychange',visibilityHandler);
  if(a.detectWindowBlur)blurHandler=()=>{if(document.getElementById('proctor')&&!document.hidden)violation('window focus lost')};
  if(blurHandler)window.addEventListener('blur',blurHandler);
  if(a.requireFullscreen&&document.documentElement.requestFullscreen){
    try{await document.documentElement.requestFullscreen()}catch(e){violation('fullscreen not enabled')}
    fullscreenHandler=()=>{if(document.getElementById('proctor')&&!document.fullscreenElement)violation('fullscreen exited')};
    document.addEventListener('fullscreenchange',fullscreenHandler);
  }

  let seconds=(a.durationMinutes||30)*60;
  const timer=setInterval(()=>{
    seconds--;
    if(seconds<=0){clearInterval(timer);window.finishExam(false);return}
    const m=Math.floor(seconds/60),ss=String(seconds%60).padStart(2,'0');
    const tm=$('#timer');if(tm)tm.textContent=`${m}:${ss}`;
  },1000);

  window.finishExam=async(auto)=>{
    if(finished)return;
    saveCurrent(); finished=true; clearInterval(timer);
    if(stream)stream.getTracks().forEach(t=>t.stop());
    if(visibilityHandler)document.removeEventListener('visibilitychange',visibilityHandler);
    if(blurHandler)window.removeEventListener('blur',blurHandler);
    if(fullscreenHandler)document.removeEventListener('fullscreenchange',fullscreenHandler);
    if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});
    clearClipboardHandlers();
    overlay.remove();
    delete window.finishExam; delete window.nextExamQuestion; delete window.prevExamQuestion; delete window.submitExamNow; delete window.runCurrentExamCode; delete window.clearCurrentExamOutput;
    try{
      const result=await api(`/api/assessments/${id}/attempt`,{method:'POST',body:JSON.stringify({answers,violations,autoSubmitted:auto})});
      openModal('Assessment Result',`<div class="card" style="text-align:center"><div class="meta">${auto?'Automatically submitted because the configured violation limit was reached.':'Assessment submitted successfully.'}</div><div style="font-size:36px;font-weight:800;margin:12px 0">${result.score||0}/${result.total||0}</div><div class="pill">Score: ${result.total?Math.round((result.score||0)*100/result.total):0}%</div><div class="pill" style="margin-left:6px">Violations: ${result.violations||0}</div></div><button class="btn" onclick="closeModal();route('career')">Back to Career Studio</button>`);
    }catch(e){toast(e.message);route('career')}
  };

  renderQuestion();
}
function resume(){const r=renderResume();app.innerHTML=`<div class="card hero"><div><h2>Professional Resume Studio</h2><p>Turn your StudentGig profile into a clean, ATS-friendly resume designed for real applications.</p></div><div class="hero-side"><small>PROFILE</small><strong>${profileScore()}%</strong><small>Data available</small></div></div><div class="resume-actions section"><button class="btn" onclick="generateAIResume()">✦ Generate with AI</button><button class="btn secondary" onclick="window.print()">Print / Save PDF</button><button class="btn secondary" onclick="route('profile')">Edit profile</button></div><div class="notice" style="margin-bottom:12px">Best results come from complete skills, projects, experience, education and achievement details. The AI must not invent facts.</div><div class="resume-wrap" id="resumeArea">${r}</div>`}
function renderResume(){return `<article class="resume-paper professional-resume"><div class="resume-name">${esc(me.name||'Your Name')}</div><div class="resume-role">${esc(me.degree||'Student')} ${me.graduationYear?'· Class of '+esc(me.graduationYear):''}</div><div class="resume-contact">${esc(me.email||'')}${me.phone?' · '+esc(me.phone):''}${me.location?' · '+esc(me.location):''}<br>${[me.linkedin,me.github,me.portfolio].filter(Boolean).map(esc).join(' · ')}</div><h3>PROFILE</h3><p>${esc(me.bio||'Motivated student seeking an opportunity to apply technical skills and contribute to meaningful projects.')}</p><h3>CORE SKILLS</h3><p>${esc(me.skills||'Add your skills in My Profile.')}</p><h3>EXPERIENCE</h3><p>${esc(me.experience||'Add internships, projects, leadership and measurable achievements in My Profile.')}</p><h3>EDUCATION</h3><p><b>${esc(me.degree||'Degree')}</b>${me.graduationYear?' · '+esc(me.graduationYear):''}</p><h3>ACHIEVEMENTS & CERTIFICATIONS</h3><p>Add certifications, coding achievements, projects and awards to your profile for inclusion in the AI version.</p></article>`}
async function generateAIResume(){try{const role=prompt('Target role (example: Java Developer):','Java Developer')||'Software Developer';const jd=prompt('Optional job description for ATS tailoring:','')||'';const out=await api('/api/resume/generate',{method:'POST',body:JSON.stringify({targetRole:role,jobDescription:jd})});if(out?.html)$('#resumeArea').innerHTML=out.html;else toast('Resume generated')}catch(e){toast('Resume generation failed: '+e.message)}}
async function freelance(){let x=[];try{x=await api('/api/freelance')}catch(e){}app.innerHTML=`<div class="card hero"><div><h2>Freelance projects</h2><p>Project-based work is available here as a separate module. Your main StudentGig experience stays career and jobs first.</p></div></div><div class="card section"><div class="section-head"><h2>Opportunities</h2><button class="btn" onclick="createFreelance()">Post project</button></div><div class="jobs">${x.map(j=>`<div class="job"><div><h3>${esc(j.title)}</h3><div class="meta">${esc(j.status||'OPEN')} · ${esc(j.budget||'Discuss')}</div><div class="tags">${esc(j.skills||'').split(',').map(s=>`<span class="tag">${esc(s.trim())}</span>`).join('')}</div></div></div>`).join('')||empty('No freelance projects','Create a project when you need project-based help.')}</div></div>`}
async function admin(){if(me.role!=='ADMIN'){app.innerHTML=`<div class="card empty"><strong>Admin access required</strong>Sign in using the administrator credentials configured for this installation.</div>`;return}let st={},tests=[];try{st=await api('/api/admin/stats');tests=await api('/api/assessments/all-admin')}catch(e){toast(e.message)}app.innerHTML=`<div class="card admin-hero hero"><div><h2>Admin Control Center</h2><p>Full platform control for users, jobs, companies, assessments, coding questions and proctoring policies.</p></div><div class="hero-side"><small>ROLE</small><strong>ADMIN</strong><small>Protected session</small></div></div><div class="grid section"><div class="card stat"><small>Users</small><strong>${st.users||0}</strong></div><div class="card stat"><small>Jobs</small><strong>${st.jobs||0}</strong></div><div class="card stat"><small>Companies</small><strong>${st.companies||0}</strong></div><div class="card stat"><small>Assessments</small><strong>${tests.length||0}</strong></div></div><div class="admin-grid section"><div class="card admin-card"><h3>Assessment Builder</h3><p>Create MCQ and coding questions, sample input/output, duration and publishing rules.</p><button class="btn" onclick="createAssessment()">Create test</button></div><div class="card admin-card"><h3>Online Compiler</h3><p>Prepare and test Java 17 and Python 3 questions on the server machine.</p><button class="btn" onclick="adminCompiler()">Open compiler</button></div><div class="card admin-card"><h3>AI & Proctoring</h3><p>Configure camera, tab switching, focus loss, fullscreen and violation thresholds per test.</p><button class="btn secondary" onclick="proctorRules()">Configure rules</button></div><div class="card admin-card"><h3>Platform Management</h3><p>Review users, jobs and companies. Admin sessions have access to platform control endpoints.</p><button class="btn secondary" onclick="route('jobs')">Review marketplace</button></div><div class="card admin-card"><h3>Exam Results</h3><p>See who took each test, marks, violations and automatic submissions.</p><button class="btn" onclick="adminAttemptResults()">View results</button></div></div><div class="card section"><div class="section-head"><h2>Assessment library</h2><button class="btn" onclick="createAssessment()">+ New assessment</button></div>${tests.map(t=>`<div class="job"><div><h3>${esc(t.title)}</h3><div class="meta">${esc(t.category||'General')} · ${t.durationMinutes||30} min · ${t.cheatLimit??3} violations · ${t.requireCamera?'Camera':''}${t.detectTabSwitch?' · Tab':''}${t.requireFullscreen?' · Fullscreen':''}</div></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn secondary" onclick="takeAsAdmin(${t.id})">Preview / Take</button><button class="btn secondary" onclick="editAssessment(${t.id})">Edit</button><button class="btn danger" onclick="deleteAssessment(${t.id})">Delete</button></div></div>`).join('')||empty('No assessments','Create a test to get started.')}</div>`}
function createAssessment(){openModal('Assessment Builder',`<form class="form" onsubmit="saveAssessment(event)"><div class="builder-grid"><input id="at" class="field" required placeholder="Assessment title"><input id="ac" class="field" placeholder="Category e.g. Java Fundamentals"><input id="ad" class="field" type="number" min="1" value="30" placeholder="Duration minutes"><input id="al" class="field" type="number" min="1" value="3" placeholder="Max violations"></div><div class="check-grid"><label class="check-card"><input id="rc" type="checkbox" checked> Require camera</label><label class="check-card"><input id="dt" type="checkbox" checked> Detect tab switching</label><label class="check-card"><input id="db" type="checkbox" checked> Detect window focus loss</label><label class="check-card"><input id="rf" type="checkbox"> Require fullscreen</label><label class="check-card"><input id="bm" type="checkbox"> Block mobile devices</label></div><div id="questionBuilder"></div><div style="display:flex;gap:8px"><button type="button" class="btn secondary" onclick="addQuestionBuilder()">+ Add question</button><button class="btn">Publish assessment</button></div></form>`);addQuestionBuilder()}
let qCount=0;function addQuestionBuilder(data={}){qCount++;const wrap=document.createElement('div');wrap.className='q-builder';wrap.id='qb'+qCount;wrap.innerHTML=`<div class="q-builder-head"><b>Question ${qCount}</b><select class="q-type"><option value="MCQ" ${data.type==='CODING'?'':'selected'}>MCQ</option><option value="CODING" ${data.type==='CODING'?'selected':''}>Coding</option></select></div><input class="field q-text" placeholder="Question text" value="${esc(data.question||'')}"><div class="q-mcq"><div class="q-options"><input class="field qo" placeholder="Option A"><input class="field qo" placeholder="Option B"><input class="field qo" placeholder="Option C"><input class="field qo" placeholder="Option D"></div><input class="field q-answer" style="margin-top:8px" placeholder="Correct answer exactly as one option"></div><div class="q-code hidden"><div class="builder-grid"><select class="field q-lang"><option value="java">Java 17</option><option value="python">Python 3</option></select><input class="field q-in" placeholder="Sample input"><input class="field q-out" placeholder="Sample output"></div><textarea class="field q-starter" placeholder="Starter code (optional)"></textarea><div class="hidden-tests"><b style="font-size:10px">Hidden test cases</b><div class="builder-grid"><textarea class="field q-hin" placeholder="Hidden input, one case per line/block"></textarea><textarea class="field q-hout" placeholder="Expected output, one case per line/block"></textarea></div></div></div>`;$('#questionBuilder').appendChild(wrap);const sel=wrap.querySelector('.q-type');sel.onchange=()=>{wrap.querySelector('.q-mcq').classList.toggle('hidden',sel.value!=='MCQ');wrap.querySelector('.q-code').classList.toggle('hidden',sel.value!=='CODING')};sel.dispatchEvent(new Event('change'))}
function collectQuestions(){return [...document.querySelectorAll('.q-builder')].map(w=>{const type=w.querySelector('.q-type').value,q={type,question:w.querySelector('.q-text').value};if(type==='MCQ'){q.options=[...w.querySelectorAll('.qo')].map(x=>x.value).filter(Boolean);q.answer=w.querySelector('.q-answer').value}else{q.language=w.querySelector('.q-lang').value;q.sampleInput=w.querySelector('.q-in').value;q.sampleOutput=w.querySelector('.q-out').value;q.starterCode=w.querySelector('.q-starter').value;const hi=w.querySelector('.q-hin').value.trim().split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);const ho=w.querySelector('.q-hout').value.trim().split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);q.hiddenTests=hi.map((input,i)=>({input,output:ho[i]||''}))}return q})}
async function saveAssessment(e){e.preventDefault();try{const qs=collectQuestions();if(!qs.length)throw Error('Add at least one question');if(qs.some(q=>!q.question))throw Error('Every question needs text');await api('/api/assessments/admin',{method:'POST',body:JSON.stringify({title:$('#at').value,category:$('#ac').value,durationMinutes:Number($('#ad').value),cheatLimit:Number($('#al').value),requireCamera:$('#rc').checked,detectTabSwitch:$('#dt').checked,detectWindowBlur:$('#db').checked,requireFullscreen:$('#rf').checked,blockMobile:$('#bm').checked,questionsJson:JSON.stringify(qs),active:true})});closeModal();toast('Assessment published');qCount=0;admin()}catch(e){toast(e.message)}}
async function editAssessment(id){try{const a=await api('/api/assessments/'+id);let qs=[];try{qs=JSON.parse(a.questionsJson||'[]')}catch(e){}openModal('Edit assessment',`<form class="form" onsubmit="updateAssessment(event,${id})"><div class="builder-grid"><input id="et" class="field" required value="${esc(a.title)}"><input id="ec" class="field" value="${esc(a.category||'')}"><input id="ed" class="field" type="number" min="1" value="${a.durationMinutes||30}"><input id="el" class="field" type="number" min="1" value="${a.cheatLimit||3}"></div><div class="check-grid"><label class="check-card"><input id="erc" type="checkbox" ${a.requireCamera?'checked':''}> Require camera</label><label class="check-card"><input id="edt" type="checkbox" ${a.detectTabSwitch?'checked':''}> Detect tab switching</label><label class="check-card"><input id="edb" type="checkbox" ${a.detectWindowBlur?'checked':''}> Detect focus loss</label><label class="check-card"><input id="erf" type="checkbox" ${a.requireFullscreen?'checked':''}> Require fullscreen</label><label class="check-card"><input id="ebm" type="checkbox" ${a.blockMobile?'checked':''}> Block mobile</label></div><div id="editQB"></div><button class="btn">Save changes</button></form>`);qCount=0;qs.forEach(q=>{const w=document.createElement('div');w.className='q-builder';w.innerHTML=`<div class="q-builder-head"><b>Question</b><span class="pill">${esc(q.type||'MCQ')}</span></div><textarea class="field eq-json" style="min-height:150px">${esc(JSON.stringify(q,null,2))}</textarea>`;$('#editQB').appendChild(w)})}catch(e){toast(e.message)}}
async function updateAssessment(e,id){e.preventDefault();try{const qs=[...document.querySelectorAll('.eq-json')].map(x=>JSON.parse(x.value));await api('/api/assessments/admin/'+id,{method:'PUT',body:JSON.stringify({title:$('#et').value,category:$('#ec').value,durationMinutes:Number($('#ed').value),cheatLimit:Number($('#el').value),requireCamera:$('#erc').checked,detectTabSwitch:$('#edt').checked,detectWindowBlur:$('#edb').checked,requireFullscreen:$('#erf').checked,blockMobile:$('#ebm').checked,questionsJson:JSON.stringify(qs),active:true})});closeModal();toast('Assessment updated');admin()}catch(e){toast('Fix the question JSON: '+e.message)}}
async function deleteAssessment(id){if(!confirm('Delete this assessment?'))return;try{await api('/api/assessments/admin/'+id,{method:'DELETE'});toast('Assessment deleted');admin()}catch(e){toast(e.message)}}
